  if (response.error) {
    const e = response.error;
    const msg = typeof e === 'string' ? e : e.message || e.type || JSON.stringify(e);
    return fail(`API error: ${String(msg).slice(0, 200)}`);
  }
  if (response.stop_reason === 'refusal') return fail('model declined to answer');
  if (response.stop_reason === 'max_tokens') return fail('answer was cut off (max_tokens)');

  const blocks = Array.isArray(response.content) ? response.content : [];
  const textBlock = blocks.find((b) => b && b.type === 'text' && typeof b.text === 'string');
  if (!textBlock) return fail('no text block in response');

  let text = textBlock.text.trim();
  // Defensive: strip a markdown fence if one ever appears.
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    return fail('answer was not valid JSON');
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) return fail('answer was not a JSON object');
  if (!RATINGS.includes(data.rating)) return fail(`rating "${data.rating}" is not Hot, Warm or Cold`);
  if (typeof data.reason !== 'string' || !data.reason.trim()) return fail('reason is missing');

  return {
    ok: true,
    rating: data.rating,
    reason: data.reason.trim().slice(0, MAX_REASON),
    nextStep: typeof data.next_step === 'string' ? data.next_step.trim().slice(0, 200) : '',
    error: null,
  };
}

// Final word after the retry: a good parse wins, otherwise Warm + needs review,
// so a broken AI step never drops a lead or wrongly marks it Cold.
function finalRating(parsed, attempts) {
  if (parsed && parsed.ok) {
    return { rating: parsed.rating, reason: parsed.reason, nextStep: parsed.nextStep, needsReview: false, attempts, ratingError: '' };
  }
  const why = (parsed && parsed.error) || 'unknown error';
  return {
    rating: 'Warm',
    reason: `Automatic rating failed (${why}). Defaulted to Warm, please review by hand.`,
    nextStep: 'Read the enquiry and rate it manually.',
    needsReview: true,
    attempts,
    ratingError: why,
  };
}

if (typeof module !== 'undefined') {
  module.exports = { MODEL, RATINGS, RATING_SCHEMA, systemPrompt, buildClaudeRequest, parseRating, finalRating };
}

// Text for the Slack alert, the welcome email, the Sheet row and the error alert.
// Runs inside n8n Code nodes and in the unit tests. Pure functions.

function sheetRow(lead, result) {
  return {
    received_at: lead.receivedAt,
    email: lead.email,
    name: lead.name,
    company: lead.company,
    budget: lead.budget,
    source: lead.source,
    rating: result.rating,
    reason: result.reason,
    next_step: result.nextStep,
    needs_review: result.needsReview ? 'yes' : 'no',
    ai_attempts: result.attempts,
    message: lead.message,
  };
}

function slackText(lead, result) {
  const who = lead.company ? `${lead.name} (${lead.company})` : lead.name;
  return [
    `:fire: *Hot lead:* ${who}`,
    `*Email:* ${lead.email}${lead.budget ? `   *Budget:* ${lead.budget}` : ''}`,
    `*Why hot:* ${result.reason}`,
    `*Next step:* ${result.nextStep}`,
    `> ${lead.message.slice(0, 300)}${lead.message.length > 300 ? '...' : ''}`,
  ].join('\n');
}

function welcomeEmail(lead, businessName) {
  const first = lead.firstName || 'there';
  return {
    subject: `Thanks for getting in touch with ${businessName}`,
    body: [
      `Hi ${first},`,
      '',
      `Thanks for your message. It has reached the team at ${businessName} and someone will reply within one working day.`,
      '',
      'If anything is urgent, just reply to this email and add a line about the deadline.',
      '',
      'Best regards,',
      businessName,
    ].join('\n'),
  };
}

function errorAlert(err) {
  const ex = (err && err.execution) || {};
  const wf = (err && err.workflow) || {};
  const e = ex.error || {};
  const node = (e.node && e.node.name) || ex.lastNodeExecuted || 'unknown node';
  return {
    subject: `n8n failure: ${wf.name || 'workflow'} at "${node}"`,
    body: [
      `Workflow: ${wf.name || '(unknown)'}`,
      `Failed node: ${node}`,
      `Error: ${e.message || '(no message)'}`,
      `Execution: ${ex.url || ex.id || '(no link)'}`,
      `Mode: ${ex.mode || '(unknown)'}`,
      '',
      'Open the execution link to see the input that failed, fix the cause, then retry the execution from n8n.',
    ].join('\n'),
  };
}

if (typeof module !== 'undefined') module.exports = { sheetRow, slackText, welcomeEmail, errorAlert };

// ---- n8n glue ----
const result = finalRating($json.parsed, $json.attempts);
const lead = $json.lead;
const businessName = $('Config').first().json.business_name;
return { json: { lead, result, sheet_row: sheetRow(lead, result), slack_text: slackText(lead, result), welcome: welcomeEmail(lead, businessName) } };
